using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Plain reference holder for the Song Selection PREFAB (Assets/_Project/Prefabs/UI/SongSelection.prefab,
/// generated by FrontendScreenPrefabs — Tools > MusicGame > UI > Build All UI Prefabs — and edited by hand
/// from then on). The static chrome (title, scrollable song list, Play Your Song, streaming row, back/play
/// buttons, status text) lives here; the catalog rows are SongRow item prefabs (UIPrefabLibrarySO.songRow)
/// that SongSelectionController spawns into songListRoot (VerticalLayoutGroup + ContentSizeFitter: spacing
/// edited here) once the Addressables catalog resolves. The controller only READS these references.
/// </summary>
public class SongSelectionView : MonoBehaviour
{
    [Header("Root")]
    public GameObject   root;
    public TextMeshProUGUI titleText;

    [Header("Song list (SongRow prefabs spawned at runtime)")]
    public RectTransform songListRoot;

    [Header("Play Your Song — a standalone button, NOT part of the scrollable list")]
    public Button      playYourSongButton;
    public TextMeshProUGUI playYourSongLabel;

    [Header("Streaming placeholders")]
    public Button      spotifyButton;
    public TextMeshProUGUI spotifyLabel;
    public Button      youtubeMusicButton;
    public TextMeshProUGUI youtubeMusicLabel;
    public Button      amazonMusicButton;
    public TextMeshProUGUI amazonMusicLabel;

    [Header("Bottom bar")]
    public Button      backButton;
    public TextMeshProUGUI backButtonLabel;
    public Button      playButton;
    public TextMeshProUGUI playButtonLabel;
    public TextMeshProUGUI statusText;

    [Header("State styling (applied at runtime)")]
    [Tooltip("Row / Play Your Song background when not selected.")]
    public Color rowUnselectedColor = new(1f, 1f, 1f, 0.12f);
    [Tooltip("Alpha of the theme accent colour used as the selected row's background.")]
    [Range(0f, 1f)] public float rowSelectedAlpha = 0.35f;
    [Tooltip("Accent used for the selection highlight when no Theme is active.")]
    public Color fallbackAccentColor = new(0.18f, 0.75f, 0.95f);
    public Color neutralStatusColor = new(0.75f, 0.75f, 0.75f);
    public Color errorStatusColor   = new(0.85f, 0.35f, 0.3f);
}
